class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        max_sum = 12 * n
        offset = max_sum
        size = 2 * max_sum + 1
        NEG = -1

        # dp[parity][s] = max product with alternating sum s and even/odd length
        dp0 = [NEG] * size  # even length
        dp1 = [NEG] * size  # odd length
        dp0[offset] = 1  # empty subsequence: sum 0, product 1

        for x in nums:
            ndp0 = dp0[:]
            ndp1 = dp1[:]
            for s in range(size):
                # append x to odd-length subsequence (x at even index, +x)
                if dp1[s] != NEG:
                    ns = s + x
                    if 0 <= ns < size:
                        v = dp1[s] * x
                        if v <= limit and v > ndp0[ns]:
                            ndp0[ns] = v
                # append x to even-length subsequence (x at odd index, -x)
                if dp0[s] != NEG:
                    ns = s - x
                    if 0 <= ns < size:
                        v = dp0[s] * x
                        if v <= limit and v > ndp1[ns]:
                            ndp1[ns] = v
            dp0, dp1 = ndp0, ndp1

        ans = max(dp0[offset + k], dp1[offset + k])
        return ans

