class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        pref_num = [0] * (n + 1)
        pref_cost = [0] * (n + 1)
        for i in range(n):
            pref_num[i + 1] = pref_num[i] + nums[i]
            pref_cost[i + 1] = pref_cost[i] + cost[i]

        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            best = INF
            for j in range(i):
                val = dp[j] + (pref_num[i] + k) * (pref_cost[i] - pref_cost[j])
                if val < best:
                    best = val
            dp[i] = best

        return dp[n]

