    comp_id = [-1] * (N + 1)
    comps = []  # list of list of nodes per component
    possible = True

    for s in range(1, N + 1):
        if val[s] != -1:
            continue
        cid = len(comps)
        comp = []
        val[s] = 0
        comp_id[s] = cid
        dq = deque([s])
        while dq:
            u = dq.popleft()
            comp.append(u)
            for v, z in adj[u]:
                need = val[u] ^ z
                if val[v] == -1:
                    val[v] = need
                    comp_id[v] = cid
                    dq.append(v)
                elif val[v] != need:
                    possible = False
        comps.append(comp)
        if not possible:
            break

    if not possible:
        print(-1)
        return

    ans = [0] * (N + 1)
    for comp in comps:
        # For each bit, count how many nodes have it set
        # If more than half have it set, flip all values in component
        for b in range(30):
            cnt = 0
            for u in comp:
                if (val[u] >> b) & 1:
                    cnt += 1
            if cnt * 2 > len(comp):
                for u in comp:
                    val[u] ^= (1 << b)
        for u in comp:
            ans[u] = val[u]

    print(' '.join(str(ans[i]) for i in range(1, N + 1)))

