class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1

        # Step 1: Compute prefix function of str2 for KMP
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and str2[i] != str2[j]:
                j = pi[j - 1]
            if str2[i] == str2[j]:
                j += 1
            pi[i] = j

        # Step 2: Initialize word with '?' (unknown)
        word = ['?'] * L

        # Step 3: Apply all 'T' constraints
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if word[pos] != '?' and word[pos] != str2[j]:
                        return ""
                    word[pos] = str2[j]

        # Step 4: Fill remaining '?' with 'a' (lexicographically smallest)
        for i in range(L):
            if word[i] == '?':
                word[i] = 'a'

        # Step 5: Check all 'F' constraints and fix violations
        # For each F position, find the rightmost position we can change
        for i in range(n):
            if str1[i] == 'F':
                # Check if word[i..i+m-1] == str2
                match = True
                for j in range(m):
                    if word[i + j] != str2[j]:
                        match = False
                        break

                if match:
                    # Need to change some position in [i, i+m-1]
                    # Find rightmost position not fixed by a T constraint
                    changed = False
                    for j in range(m - 1, -1, -1):
                        pos = i + j
                        # Check if this position is constrained by any T
                        is_fixed = False
                        for k in range(max(0, pos - m + 1), min(pos + 1, n)):
                            if str1[k] == 'T' and k <= pos < k + m:
                                is_fixed = True
                                break

                        if not is_fixed:
                            # Change this position to something != str2[j]
                            # Use 'b' if str2[j] == 'a', else 'a'
                            word[pos] = 'b' if str2[j] == 'a' else 'a'
                            changed = True
                            break

                    if not changed:
                        return ""

        # Step 6: Verify all constraints are satisfied
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    if word[i + j] != str2[j]:
                        return ""
            else:
                match = True
                for j in range(m):
                    if word[i + j] != str2[j]:
                        match = False
                        break
                if match:
                    return ""

        return ''.join(word)

