class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Map each boundary point to its distance along the perimeter starting from (0,0)
        # Order: (0,0) -> (side,0) -> (side,side) -> (0,side) -> (0,0)
        def pos(p):
            x, y = p
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 2 * side + (side - x)
            return 3 * side + (side - y)

        P = 4 * side
        arr = sorted(pos(p) for p in points)
        n = len(arr)

        # Check if we can select at least k points with pairwise circular distance >= d
        def ok(d: int) -> bool:
            # Try each point as the first selected point
            for start in range(n):
                cnt = 1
                last = arr[start]
                # Greedily select the next point at distance >= d along the perimeter
                for i in range(start + 1, n):
                    if arr[i] - last >= d:
                        cnt += 1
                        last = arr[i]
                        if cnt == k:
                            # Check wrap-around distance between last and first
                            if P - (last - arr[start]) >= d:
                                return True
                            break
            return False

        lo, hi = 0, P // 2
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

