        for j, c in enumerate(s):
            if c != '-':
                adj[i].append((j, c))

    INF = -1
    dist = [[INF]*N for _ in range(N)]
    dq = deque()

    # Initialize with length 0 (i,i) and length 1 edges
    for i in range(N):
        dist[i][i] = 0
        dq.append((i, i))
    for u in range(N):
        for v, c in adj[u]:
            if dist[u][v] == INF or dist[u][v] > 1:
                dist[u][v] = 1
                dq.append((u, v))

    # BFS on pair graph
    while dq:
        u, v = dq.popleft()
        d = dist[u][v]
        # Try to extend by one edge on both sides with same label
        for u2, c1 in adj[u]:
            for v2, c2 in adj[v]:
                if c1 == c2:
                    if dist[u2][v2] == INF:
                        dist[u2][v2] = d + 2
                        dq.append((u2, v2))

    # Output
    out_lines = []
    for i in range(N):
        out_lines.append(' '.join(map(str, dist[i])))
