MOD = 998244353

def main():
    data = sys.stdin.read().split()
    W, H, L, R, D, U = map(int, data)
    N = W + H + 5
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i-1] * i % MOD
    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i-1] = invfact[i] * i % MOD

    def comb(n, k):
        if k < 0 or k > n or n < 0:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD

    def paths(x1, y1, x2, y2):
        if x2 < x1 or y2 < y1:
            return 0
        return comb((x2 - x1) + (y2 - y1), x2 - x1)

    def rect_sum(x1, y1, x2, y2):
        if x1 > x2 or y1 > y2:
            return 0
        return comb((x2 - x1) + (y2 - y1) + 2, x2 - x1 + 1)

    ans = 0
    # Region A: x < L
    if L > 0:
        ans = (ans + rect_sum(0, 0, L - 1, H)) % MOD
    # Region B: x > R
    if R < W:
        ans = (ans + rect_sum(R + 1, 0, W, H)) % MOD
    # Region C: L <= x <= R, y < D
    if D > 0:
        ans = (ans + rect_sum(L, 0, R, D - 1)) % MOD
    # Region D: L <= x <= R, y > U
    if U < H:
        ans = (ans + rect_sum(L, U + 1, R, H)) % MOD

    # Cross A->C
    if L > 0 and D > 0:
        s = 0
        for y in range(D):
            s = (s + paths(L - 1, y, L, D - 1)) % MOD
        ans = (ans + rect_sum(0, 0, L - 1, D - 1) * s) % MOD
    # Cross A->D
    if L > 0 and U < H:
        s = 0
        for y in range(U + 1, H + 1):
            s = (s + paths(L - 1, y, L, H)) % MOD
        ans = (ans + rect_sum(0, 0, L - 1, H) * s) % MOD
    # Cross C->B
    if D > 0 and R < W:
        s = 0
        for x in range(L, R + 1):
            s = (s + paths(x, D - 1, R + 1, D)) % MOD
        ans = (ans + rect_sum(L, 0, R, D - 1) * s) % MOD
    # Cross D->B
    if U < H and R < W:
        s = 0
        for x in range(L, R + 1):
            s = (s + paths(x, H, R + 1, U + 1)) % MOD
        ans = (ans + rect_sum(L, U + 1, R, H) * s) % MOD

    print(ans % MOD)

