class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        # Precompute cost to change each character to each letter
        cost = [[0] * 26 for _ in range(n)]
        for i in range(n):
            orig = ord(caption[i]) - ord('a')
            for j in range(26):
                cost[i][j] = abs(orig - j)

        # dp[i][j] = (min_cost, path) for prefix ending at i with character j
        # where the last group is complete (length >= 3)
        INF = float('inf')

        # Initialize: first group must have length >= 3
        dp = [[INF] * 26 for _ in range(n)]
        parent = [[None] * 26 for _ in range(n)]

        # For position 2 (first group of exactly 3)
        for j in range(26):
            dp[2][j] = cost[0][j] + cost[1][j] + cost[2][j]
            parent[2][j] = (-1, -1)  # Start marker

        # Fill DP
        for i in range(3, n):
            for j in range(26):
                # Option 1: Extend previous group (previous char was also j)
                if dp[i-1][j] != INF:
                    new_cost = dp[i-1][j] + cost[i][j]
                    if new_cost < dp[i][j]:
                        dp[i][j] = new_cost
                        parent[i][j] = (i-1, j)

                # Option 2: Start new group of length 3
                if i >= 3:
                    for k in range(26):
                        if dp[i-3][k] != INF:
                            new_cost = dp[i-3][k] + cost[i-2][j] + cost[i-1][j] + cost[i][j]
                            if new_cost < dp[i][j]:
                                dp[i][j] = new_cost
                                parent[i][j] = (i-3, k)

        # Find minimum cost at position n-1
        min_cost = INF
        best_char = -1
        for j in range(26):
            if dp[n-1][j] < min_cost:
                min_cost = dp[n-1][j]
                best_char = j

        if min_cost == INF:
            return ""

        # Reconstruct the string
        result = [''] * n
        i, j = n-1, best_char

        while i >= 0:
            if parent[i][j] == (-1, -1):
                # First group of 3
                for k in range(i, i-3, -1):
                    result[k] = chr(j + ord('a'))
                break

            pi, pj = parent[i][j]
            if pi == i - 1 and pj == j:
                # Extension of same group
                result[i] = chr(j + ord('a'))
                i, j = pi, pj
            else:
                # New group of 3
                result[i] = chr(j + ord('a'))
                result[i-1] = chr(j + ord('a'))
                result[i-2] = chr(j + ord('a'))
                i, j = pi, pj

        return ''.join(result)

