import sys

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    L = [0] * N
    R = [0] * N
    for i in range(N):
        L[i] = int(data[idx]); R[i] = int(data[idx+1]); idx += 2
    Q = int(data[idx]); idx += 1
    queries = [int(data[idx + i]) for i in range(Q)]

    MAXV = 500000
    size = 1
    while size < MAXV + 2:
        size <<= 1

    INF = 10**18
    # lazy_add[v]: pending addition to all values in node v's range
    # lazy_set[v]: pending "set to max(value, c)" operation; INF means none
    lazy_add = [0] * (2 * size)
    lazy_set = [INF] * (2 * size)

    def apply_add(v, val):
        lazy_add[v] += val
        if lazy_set[v] != INF:
            lazy_set[v] += val

    def apply_set(v, c):
        # set: x -> max(x, c)
        if lazy_set[v] == INF:
            lazy_set[v] = c
        else:
            if c > lazy_set[v]:
                lazy_set[v] = c

    def push(v):
        a = lazy_add[v]
        s = lazy_set[v]
        if a != 0 or s != INF:
            for c in (v * 2, v * 2 + 1):
                if s != INF:
                    apply_set(c, s)
                if a != 0:
                    apply_add(c, a)
            lazy_add[v] = 0
            lazy_set[v] = INF

    # range add +1 on [l, r]
    def range_add(l, r, v=1, tl=0, tr=None):
        if tr is None:
            tr = size - 1
        if l > r or l > tr or r < tl:
            return
        if l <= tl and tr <= r:
            apply_add(v, 1)
            return
        push(v)
        tm = (tl + tr) // 2
        range_add(l, r, v * 2, tl, tm)
        range_add(l, r, v * 2 + 1, tm + 1, tr)

    # range set-to-max on [l, r]: x -> max(x, c)
    def range_setmax(l, r, c, v=1, tl=0, tr=None):
        if tr is None:
            tr = size - 1
        if l > r or l > tr or r < tl:
            return
        if l <= tl and tr <= r:
            apply_set(v, c)
            return
        push(v)
        tm = (tl + tr) // 2
        range_setmax(l, r, c, v * 2, tl, tm)
        range_setmax(l, r, c, v * 2 + 1, tm + 1, tr)

    # point query
    def point_query(pos):
        v = 1
        tl, tr = 0, size - 1
        add_acc = 0
        set_acc = INF
        while True:
            if lazy_set[v] != INF:
                if set_acc == INF or lazy_set[v] > set_acc:
                    set_acc = lazy_set[v]
            add_acc += lazy_add[v]
            if tl == tr:
                break
            tm = (tl + tr) // 2
            if pos <= tm:
                v = v * 2
                tr = tm
            else:
                v = v * 2 + 1
                tl = tm + 1
        res = pos
        if set_acc != INF and set_acc > res:
            res = set_acc
        res += add_acc
        return res

    for i in range(N):
        Li = L[i]
        Ri = R[i]
        # For rating x in [Li, Ri]: x -> x+1
        # Equivalent: for x in [Li, Ri-1]: x -> x+1; for x = Ri: x -> Ri+1
        # We do: add +1 to [Li, Ri-1], and setmax(Ri, Ri+1)
        if Li <= Ri - 1:
            range_add(Li, Ri - 1)
        range_setmax(Ri, Ri, Ri + 1)

    out = []
    for x in queries:
        out.append(str(point_query(x)))
    sys.stdout.write("\n".join(out) + "\n")

