    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def canAchieve(maxLen: int) -> bool:
            # Check if we can make all runs of identical chars <= maxLen
            # using at most numOps flips
            ops = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                run_length = j - i
                # For a run of length L, we need to break it into pieces of size <= maxLen
                # Minimum flips needed: floor((L - 1) / maxLen)
                if run_length > maxLen:
                    ops += (run_length - 1) // maxLen
                i = j
            return ops <= numOps

        # Binary search on the answer
        left, right = 1, n
        while left < right:
            mid = (left + right) // 2
            if canAchieve(mid):
                right = mid
            else:
                left = mid + 1

        return left

class Solution:
    def makeStringGood(self, s: str) -> int:
        n = len(s)
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1

        INF = float('inf')
        ans = INF

        for target in range(1, n + 1):
            # dp[i][j] = min cost processing letters 0..i-1, with j extra
            # characters carried into letter i (from letter i-1)
            dp = [[INF] * (target + 1) for _ in range(27)]
            dp[0][0] = 0
            for i in range(26):
                for j in range(target + 1):
                    if dp[i][j] == INF:
                        continue
                    total = cnt[i] + j
                    # Option 1: keep letter i at exactly `target` occurrences
                    if total >= target:
                        # delete extras, or change extras to next letter
                        cost = dp[i][j] + (total - target)
                        if cost < dp[i + 1][0]:
                            dp[i + 1][0] = cost
                        # change extras to next letter (not allowed for 'z')
                        if i < 25:
                            carry = total - target
                            if carry <= target and cost < dp[i + 1][carry]:
                                dp[i + 1][carry] = cost
                    else:
                        # insert missing characters
                        cost = dp[i][j] + (target - total)
                        if cost < dp[i + 1][0]:
                            dp[i + 1][0] = cost
                    # Option 2: eliminate letter i entirely
                    # delete all, or change all to next letter
                    cost = dp[i][j] + total
                    if cost < dp[i + 1][0]:
                        dp[i + 1][0] = cost
                    if i < 25 and total <= target:
                        if cost < dp[i + 1][total]:
                            dp[i + 1][total] = cost
            if dp[26][0] < ans:
                ans = dp[26][0]

        return ans

from typing import List
from math import gcd

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return
            if rank[px] < rank[py]:
                px, py = py, px
            parent[py] = px
            if rank[px] == rank[py]:
                rank[px] += 1

        # Group indices by their value
        value_to_index = {}
        for i, num in enumerate(nums):
            value_to_index[num] = i

        # For each possible lcm value <= threshold, find all pairs (a, b) with lcm(a, b) = l
        # and union the corresponding nodes
        for l in range(1, threshold + 1):
            # Find all divisors of l that are present in nums
            divisors = []
            d = 1
            while d * d <= l:
                if l % d == 0:
                    if d in value_to_index:
                        divisors.append(d)
                    if d != l // d and (l // d) in value_to_index:
                        divisors.append(l // d)
                d += 1

            # For each pair of divisors, check if their lcm is exactly l
            m = len(divisors)
            for i in range(m):
                for j in range(i + 1, m):
                    a, b = divisors[i], divisors[j]
                    if a * b // gcd(a, b) == l:
                        union(value_to_index[a], value_to_index[b])

        # Count unique roots
        roots = set()
        for i in range(n):
            roots.add(find(i))

        return len(roots)
